import ast, json, os
from pathlib import Path

inputs = Path('/inputs')
work = Path('/work')

# Read inert reference text as requested
ref_path = inputs / 'smell-catalog.md'
if ref_path.exists():
    _ = ref_path.read_text(encoding='utf-8')

# Collect top-level Python source files with exclusions
py_files = []
for p in sorted(inputs.iterdir(), key=lambda x: x.name):
    if not p.is_file():
        continue
    if p.suffix != '.py':
        continue
    n = p.name
    if n == '__init__.py':
        continue
    if n.startswith('test_'):
        continue
    if n.endswith('_test.py'):
        continue
    py_files.append(p)

included_names = [p.name for p in py_files]
included_stems = {p.stem for p in py_files}

# Line counts using splitlines semantics
line_counts = {}
contents = {}
for p in py_files:
    txt = p.read_text(encoding='utf-8')
    contents[p.name] = txt
    line_counts[p.name] = len(txt.splitlines())

# Parse imports and build graph
edges = {p.name: set() for p in py_files}

for p in py_files:
    name = p.name
    stem = p.stem
    src = contents[name]
    try:
        tree = ast.parse(src, filename=str(p))
    except SyntaxError:
        # If syntactically invalid, no import edges can be reliably extracted
        continue

    for node in ast.walk(tree):
        target_stems = []

        if isinstance(node, ast.Import):
            for alias in node.names:
                mod = alias.name
                if mod == 'skillc.frontend' or mod.startswith('skillc.frontend.'):
                    rest = mod[len('skillc.frontend'):]
                    if rest.startswith('.'):
                        rest = rest[1:]
                    if rest:
                        first = rest.split('.')[0]
                        target_stems.append(first)

        elif isinstance(node, ast.ImportFrom):
            level = node.level or 0
            module = node.module

            # Explicit absolute imports under skillc.frontend
            if level == 0 and module is not None and (module == 'skillc.frontend' or module.startswith('skillc.frontend.')):
                if module == 'skillc.frontend':
                    # from skillc.frontend import foo
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        first = alias.name.split('.')[0]
                        target_stems.append(first)
                else:
                    rest = module[len('skillc.frontend.'):]
                    if rest:
                        first = rest.split('.')[0]
                        target_stems.append(first)

            # Level-one relative imports only
            elif level == 1:
                if module:
                    # from .module import x
                    first = module.split('.')[0]
                    target_stems.append(first)
                else:
                    # from . import module
                    for alias in node.names:
                        if alias.name == '*':
                            continue
                        first = alias.name.split('.')[0]
                        target_stems.append(first)

        for t in target_stems:
            if t in included_stems and t != stem:
                edges[name].add(f'{t}.py')

# files rows
files_rows = []
for n in sorted(included_names):
    files_rows.append({
        'name': n,
        'lines': int(line_counts[n]),
        'imports': sorted(edges[n]),
    })

# prefix clusters
stems = sorted([Path(n).stem for n in included_names])
prefix_to_members = {}
for s in stems:
    for L in range(4, len(s) + 1):
        pref = s[:L]
        members = tuple(sorted(m for m in stems if m.startswith(pref)))
        if len(members) >= 3:
            prefix_to_members[pref] = frozenset(members)

# Group by member set and collapse to longest common prefix
member_set_to_prefix = {}
for pref, mset in prefix_to_members.items():
    member_set_to_prefix.setdefault(mset, []).append(pref)

def lcp(strings):
    if not strings:
        return ''
    s1 = min(strings)
    s2 = max(strings)
    i = 0
    n = min(len(s1), len(s2))
    while i < n and s1[i] == s2[i]:
        i += 1
    return s1[:i]

prefix_rows = []
for mset in member_set_to_prefix:
    members = sorted(mset)
    pref = lcp(members)
    # safety: ensure at least 4 chars as per rule
    if len(pref) < 4:
        continue
    basenames = [f'{m}.py' for m in members]
    total_lines = sum(line_counts[b] for b in basenames)
    prefix_rows.append({
        'prefix': pref,
        'files': sorted(basenames),
        'lines': int(total_lines),
    })

prefix_rows.sort(key=lambda r: r['prefix'])

# import-tree clusters
# adjacency already in edges
import_tree_rows = []
for root in sorted(included_names):
    direct = edges[root]
    if len(direct) < 3:
        continue
    visited = set()
    stack = [root]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        for nxt in edges.get(cur, ()):
            if nxt not in visited:
                stack.append(nxt)
    if len(visited) >= 5:
        import_tree_rows.append({
            'root': root,
            'files': sorted(visited),
            'lines': int(sum(line_counts[f] for f in visited)),
        })

import_tree_rows.sort(key=lambda r: r['root'])

out = {
    'files': files_rows,
    'prefix_clusters': prefix_rows,
    'import_tree_clusters': import_tree_rows,
}

out_path = work / 'layout.json'
out_path.write_text(json.dumps(out, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

# Basic validation: exact top keys and integer counts
loaded = json.loads(out_path.read_text(encoding='utf-8'))
assert list(loaded.keys()) == ['files', 'prefix_clusters', 'import_tree_clusters']
for row in loaded['files']:
    assert set(row.keys()) == {'name','lines','imports'}
    assert isinstance(row['lines'], int) and not isinstance(row['lines'], bool)
for row in loaded['prefix_clusters']:
    assert set(row.keys()) == {'prefix','files','lines'}
    assert isinstance(row['lines'], int) and not isinstance(row['lines'], bool)
for row in loaded['import_tree_clusters']:
    assert set(row.keys()) == {'root','files','lines'}
    assert isinstance(row['lines'], int) and not isinstance(row['lines'], bool)

print(f'Wrote {out_path} with {len(files_rows)} files, {len(prefix_rows)} prefix clusters, {len(import_tree_rows)} import-tree clusters.')
